+import sales from './sales.json' with { type: 'json' };
+
+const SALES_REPORT_TOOL = {
+  name: 'sales_report',
+  description:
+    'Sum the amounts of sales rows that fall within an inclusive date range. ' +
+    'Both start_date and end_date are required ISO date strings (YYYY-MM-DD) and ' +
+    'both endpoints are included in the sum. Returns the total amount and the ' +
+    'number of rows matched as text content.',
+  inputSchema: {
+    type: 'object',
+    properties: {
+      start_date: {
+        type: 'string',
+        description: 'Inclusive start of the range as an ISO date (YYYY-MM-DD).'
+      },
+      end_date: {
+        type: 'string',
+        description: 'Inclusive end of the range as an ISO date (YYYY-MM-DD).'
+      }
+    },
+    required: ['start_date', 'end_date'],
+    additionalProperties: false
+  }
+};
+
+// Strict ISO calendar-date check: exactly YYYY-MM-DD with zero padding and a
+// real calendar date (rejects e.g. 2026-13-01, 2026-02-30, 2026-1-1, "notadate").
+function isValidISODate(s) {
+  if (typeof s !== 'string') return false;
+  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
+  if (!m) return false;
+  const y = Number(m[1]);
+  const mo = Number(m[2]);
+  const d = Number(m[3]);
+  const date = new Date(y, mo - 1, d);
+  return (
+    date.getFullYear() === y &&
+    date.getMonth() === mo - 1 &&
+    date.getDate() === d
+  );
+}
+
+export async function listTools() {
+  return [SALES_REPORT_TOOL];
+}
+
+export async function callTool(name, args = {}) {
+  args = args || {};
+
+  if (name !== 'sales_report') {
+    throw new Error(`Unknown tool: ${String(name)}`);
+  }
+
+  const allowed = ['start_date', 'end_date'];
+  const extra = Object.keys(args).filter((k) => !allowed.includes(k));
+  if (extra.length > 0) {
+    throw new Error(`Unexpected field(s): ${extra.join(', ')}`);
+  }
+
+  const { start_date, end_date } = args;
+
+  if (start_date === undefined) {
+    throw new Error('start_date is required');
+  }
+  if (end_date === undefined) {
+    throw new Error('end_date is required');
+  }
+  if (!isValidISODate(start_date)) {
+    throw new Error(`start_date is not a valid ISO date (YYYY-MM-DD): ${String(start_date)}`);
+  }
+  if (!isValidISODate(end_date)) {
+    throw new Error(`end_date is not a valid ISO date (YYYY-MM-DD): ${String(end_date)}`);
+  }
+
+  // Valid YYYY-MM-DD strings compare chronologically lexicographically.
+  if (start_date > end_date) {
+    throw new Error(`start_date (${start_date}) is after end_date (${end_date})`);
+  }
+
+  let total = 0;
+  let count = 0;
+  for (const row of sales) {
+    if (isValidISODate(row.date) && row.date >= start_date && row.date <= end_date) {
+      total += row.amount;
+      count += 1;
+    }
+  }
+
+  const text = `Total amount: ${total}\nRow count: ${count}`;
+  return { content: [{ type: 'text', text }] };
+}
